 n=min(rem,key=lambda x:len(opts[x]))
 h,w=shapes[n]
 for s,r,c in opts[n]:
  oc=occ.copy();oc[r:r+h,c:c+w]=1
  if search2(rem-{n},oc,{**pl,n:(r,c)},score+s):return True
 return False
